// spec: .qa/e2e/specs/faq-texts.md
// seed: tests/seed.spec.ts

import { test, expect } from '@playwright/test';

test.describe('FAQ texts on landing pages', () => {
  test('FAQ answers have no "ההד האנטר" on /talents @desktop @prod-safe (#24eb58)', async ({ page }) => {
    // 1. Open /talents as guest (Hebrew).
    await page.goto('/talents');

    // 2. Scroll to the FAQ section («שאלות נפוצות»).
    const faq = page.locator('section#faq');
    await faq.scrollIntoViewIfNeeded();
    await expect(faq.getByRole('heading', { name: 'שאלות נפוצות' })).toBeVisible();

    // 3. For each FAQ tab: click the tab, expand every question (+) and read the answer texts.
    const tabs = faq.getByRole('tab');
    const tabCount = await tabs.count();
    expect(tabCount).toBeGreaterThan(0);

    const answersByQuestion: Record<string, string> = {};
    let companiesTabSeen = false;

    for (let t = 0; t < tabCount; t++) {
      const tab = tabs.nth(t);
      const tabName = ((await tab.textContent()) ?? '').trim();
      await tab.click();
      await expect(tab).toHaveAttribute('aria-selected', 'true');
      if (tabName === 'חברות/ארגונים') companiesTabSeen = true;

      const panel = faq.getByRole('tabpanel');
      const questions = panel.locator('button[aria-expanded]');
      const qCount = await questions.count();
      expect(qCount).toBeGreaterThan(0);

      for (let q = 0; q < qCount; q++) {
        const button = questions.nth(q);
        const question = ((await button.locator('span').first().textContent()) ?? '').trim();
        if ((await button.getAttribute('aria-expanded')) !== 'true') {
          await button.click();
        }
        // accordion keeps one question open
        await expect(button).toHaveAttribute('aria-expanded', 'true');
        const item = button.locator('xpath=..');
        const answer = item.locator('p');
        await expect(answer).toBeVisible();
        const answerText = ((await answer.textContent()) ?? '').trim();

        expect(answerText, `empty answer: ${question}`).not.toBe('');
        expect(question, `question has "ההד האנטר": ${question}`).not.toContain('ההד האנטר');
        expect(answerText, `answer has "ההד האנטר": ${question}`).not.toContain('ההד האנטר');
        if (tabName === 'חברות/ארגונים') answersByQuestion[question] = answerText;
      }
    }

    expect(companiesTabSeen).toBe(true);
    expect(answersByQuestion['איך מפרסמים מכרז לאיתור הד האנטר?']).toContain('הד האנטרים יגישו הצעות שתוכלו להשוות');
    expect(answersByQuestion['האם אפשר לחייב NDA?']).toContain('שהד האנטרים יחתמו על הסכם סודיות');
  });
});
